// Met en forme un rapport de faible gravité pour un canal de surveillance.
//
// Pas d'archivage : ces événements sont du bruit de fond — jobs
// éphémères, replicas temporairement incomplets, dérives mémoire encore
// sous contrôle. Ils méritent d'être vus, pas conservés.
//
// Le message est délibérément compact : un canal de surveillance se
// parcourt d'un coup d'œil.

const rapport = $json.body || $json;

// Garde : une charge sans anomalie n'est pas un rapport.
if (!Array.isArray(rapport.anomalies) || rapport.anomalies.length === 0) {
  return [];
}

const namespace = rapport.namespace || '—';
const anomalies = rapport.anomalies;
const diagnostic = rapport.diagnostic || '';
const cout = rapport.cout_dollars ?? 0;

const titre = anomalies.length === 1
  ? `🔵 ${anomalies[0].ressource} ${anomalies[0].nom}`
  : `🔵 ${anomalies.length} anomalies dans ${namespace}`;

const liste = anomalies
  .map(a => `• \`${a.nom}\` — ${a.etat}` +
            (a.redemarrages ? ` (${a.redemarrages} redémarrages)` : ''))
  .join('\n');

// Seule la section « Diagnostic » du rapport : sur un canal de
// surveillance, les constats et le correctif détaillé sont du bruit.
const resume = (() => {
  const m = diagnostic.match(/##\s*Diagnostic\s*\n+([\s\S]*?)(?=\n##|$)/);
  const texte = (m ? m[1] : diagnostic).trim();
  return texte.length > 500 ? texte.slice(0, 500) + '…' : texte;
})();

return [{
  json: {
    embed: {
      title: titre,
      description: resume || '_(pas de diagnostic)_',
      color: 0x3498db,
      fields: [
        { name: 'Namespace', value: namespace, inline: true },
        { name: 'Coût', value: `${cout} $`, inline: true },
        { name: 'Anomalies', value: liste.slice(0, 1024) }
      ],
      timestamp: new Date().toISOString()
    }
  }
}];
